#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    long long total = (long long)n * (n - 1) / 2;
    long long max_x = (long long)n * (n - 1);
    vector<vector<long long>> dp(n + 1, vector<long long>(max_x + 1, 0));
    vector<vector<long long>> dp1(n + 1, vector<long long>(max_x + 1, 0));
    dp[1][total] = 1;
    for (int i = 2; i <= n; ++i) {
        long long start = total - (long long)(i - 1) * (i - 2) / 2;
        long long end = total + (long long)(i - 1) * (i - 2) / 2;
        for (long long x = start; x <= end; ++x) {
            for (int d = -i + 1; d < i; ++d) {
                long long idx = x + d;
                if (0 <= idx && idx <= max_x) {
                    dp[i][idx] = (dp[i][idx] + dp[i - 1][x] * (i - abs(d))) % m;
                }
            }
        }
        for (long long x = start; x <= end; ++x) {
            dp1[i][x] = (dp1[i - 1][x] * i) % m;
        }
        for (long long x = start; x <= end; ++x) {
            for (int d = 1; d < i; ++d) {
                long long idx = x - d;
                if (0 <= idx && idx <= max_x) {
                    dp1[i][idx] = (dp1[i][idx] + dp[i - 1][x] * (i - d)) % m;
                }
            }
        }
    }
    long long result = 0;
    for (long long x = total + 1; x <= max_x; ++x) {
        result = (result + dp1[n][x]) % m;
    }
    cout << result << "\n";
    return 0;
}
